ity.","score":"7.4","vector":"(CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:H/I:H/A:N)","type":"","reported":"2026-04-28","url":"https://www.cve.org/CVERecord?id=CVE-2026-41603"},{"id":"CVE-2026-43869","description":"Improper Validation of Certificate with Host Mismatch vulnerability in Apache Thrift.\n\nThis issue affects Apache Thrift: before 0.23.0.\n\nUsers are recommended to upgrade to version 0.23.0, which fixes the issue.","score":"7.3","vector":"(CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:L/A:L)","type":"","reported":"2026-05-05","url":"https://www.cve.org/CVERecord?id=CVE-2026-43869"}]}cvedetailsend--->", "field_affected_products": " <table border="1"><tbody><tr><td>Affected Product(s)</td><td>Version(s)</td></tr><tr><td>InfoSphere Information Server</td><td>11.7.0.0 to 11.7.1.6</td></tr></tbody></table>"}
